const GET_DESCRIPTOR_OUTPUT = mcpOutputSchema({
  type: 'object',
  description: "Descriptor Turtle plus optional decrypted graph payload reached via the descriptor's iep:hasDistribution link.",
  properties: {
    url: { type: 'string', description: 'Echo of the descriptor URL requested' },
    turtle: { type: 'string', description: 'Full Turtle of the descriptor (when the URL is a .ttl)' },
    encrypted: { type: 'boolean', description: 'For .envelope.jose.json / .trig URLs: was the payload encrypted' },
    mediaType: { type: 'string' },
    content: { type: 'string', description: 'Resolved graph payload (decrypted when this agent is a recipient)' },
    graph: {
      type: 'object',
      description: 'Distribution-followed graph payload (when descriptor has iep:hasDistribution and content was reachable)',
      properties: {
        url: { type: 'string' },
        mediaType: { type: 'string' },
        encrypted: { type: 'boolean' },
        content: { type: 'string' },
      },
    },
    authorship: {
      type: 'object',
      description: 'When the descriptor embeds a iep:authorshipProof, the relay automatically re-derives the canonical authorship payload and runs the delegation verifier from the descriptor turtle alone. authorshipVerified=true means BOTH that the signature matched and that the proof names the record it was served with (descriptorBinding.bound) — a proof lifted onto another record now answers false with the binding diagnostic as its reason, because the signature alone verifies wherever the block is pasted. When BOTH the authorship proof and the delegation chain verify, effectiveTrustLevel becomes CryptographicallyVerified even if the descriptor body shipped SelfAsserted. ★ authorshipVerified alone says WHO SIGNED A DESCRIPTOR — read contentBinding to learn whether the signature also covers the graph served with it; the two are separate questions and a proof can verify while covering nothing.',
      properties: {
        authorshipVerified: { type: 'boolean' },
        signedBy: { type: 'string', description: 'Agent IRI claimed in the proof' },
        verificationMethod: { type: 'string', description: 'did:ethr:<addr> or other key-resolution IRI' },
        effectiveTrustLevel: { type: 'string', enum: ['CryptographicallyVerified', 'SelfAsserted'] },
        contentBinding: {
          type: 'string',
          enum: ['bound', 'mismatched', 'declared', 'unbound'],
          description: 'Whether the proof covers the CONTENT served with this descriptor, not merely its URL. `bound` — the signed digest was recomputed over the payload actually served and matched; only this licenses treating the content as attested. It means the graph STATES the same triples that were signed, NOT that the bytes are identical — the payload is rewritten on publish, so the bytes never match. `mismatched` — the digest WAS recomputed and did NOT match: the signature is authentic and covers different content, so the graph has been altered since signing. Evidence against the content; authorshipVerified is also false. `declared` — the proof commits to a digest and NOTHING was checked against it (payload unreadable here, a digest form this verifier cannot recompute, or the signature failed before the content was reached); not an attestation and not an accusation. `unbound` — the proof carries no digest at all: every proof written before content binding existed, plus any payload the digester could not parse. Silent about content, and when authorshipVerified is false it is silent about the signer too.',
        },
        contentBindingNote: { type: 'string', description: 'The same verdict in prose, stating plainly what it does and does not license' },
        descriptorBinding: {
          type: 'object',
          description:
            'Whether the proof is about THIS record, which is a different question from whether its signature verified. '
            + 'A proof block lifted out of one of a principal\'s real public descriptors and pasted into a record somebody '
            + 'else fabricated verifies clean and names that principal — signature validity says the proof\'s bytes were '
            + 'not altered, not what the proof is attached to. Read this field before attributing the record to signedBy.',
          properties: {
            bound: { type: 'boolean', description: 'The proof\'s iep:descriptorId matched the URL this record was served from, and — for a URN-form id — the pod serving it publishes the same owner the proof signs' },
            basis: {
              type: 'string',
              enum: ['exact-url', 'slug-and-owner', 'slug-only', 'none'],
              description:
                'HOW it matched, because the three passing values are not equally strong. `exact-url`: the proof names an '
                + 'http(s) URL and it was compared in full (host, pod, container, name) after host normalisation — nothing '
                + 'unexamined. `slug-and-owner`: the proof names a URN, whose only defined relation to a URL is its '
                + 'terminal segment, so only that segment was matched — but the pod that SERVED the bytes publishes the '
                + 'same iep:ownerWebId the proof signs, so the record is not sitting on another party\'s pod. Still '
                + 'uncompared: the container within that pod, and the pod\'s ownership claim is the pod\'s own. '
                + '`slug-only`: the terminal segment matched and the location could not be checked at all (the proof '
                + 'carries no ownerWebId, or the serving pod publishes no readable owner) — a proof lifted onto a '
                + 'same-named record on a different pod reaches this too, which is why it is reported apart from '
                + '`slug-and-owner`. `none`: not bound — including a URN whose segment matched while the serving pod\'s '
                + 'owner DISAGREES with the signed one, which is exactly the shape of a lifted proof.',
            },
            note: { type: 'string', description: 'Names what was compared and what was not. Present on a refusal AND on both URN-form passes.' },
          },
        },
        reason: { type: 'string', description: 'Diagnostic when authorshipVerified is false' },
      },
    },
    error: { type: 'string', description: 'HTTP error from the pod when the fetch failed' },
  },
});

const LIST_KNOWN_PODS_OUTPUT = mcpOutputSchema({
  type: 'object',
  description: 'Federation pod registry snapshot. The stdio server returns a human-readable list; the relay returns the array directly under `pods`/at the top level.',
  properties: {
    addressing: { type: 'string', description: 'How to address a row: follow its `affordances`; do not compose an address out of its other fields' },
    pods: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          url: { type: 'string' },
          label: { type: 'string', description: 'Free text. NOT identity evidence: any authenticated caller can write it on any pod\'s row via add_pod, or it can arrive in an imported directory' },
          owner: { type: 'string', description: 'Free text of the same kind — NOT proof of ownership and never the row\'s identity. A did:web spelled here is reported as `claimedAgent`, not as `agent`' },
          via: { type: 'string', description: 'How the pod entered the registry (manual / directory / webfinger / home / auto — `auto` means this relay itself registered the pod\'s agent)' },
          isHome: { type: 'boolean' },
          lastSeen: { type: 'string' },
          subscribed: { type: 'boolean' },
          // ★ Declared, not just returned — and for the record, NOT because the schema was
          // bare. `git show HEAD` shows url/label/owner/via/isHome/lastSeen/subscribed were
          // all already declared, so an earlier version of this comment ("could previously
          // see only `url` and `label`") was simply false. What those seven never said is
          // WHICH of them identifies the pod, or that none of them does — so a caller
          // reading the schema to decide how to address someone still had only slugs to
          // choose between. The NINE below are the row's statement about itself, plus the
          // evidence it rests on and — since a driven `add_pod` published `surface:
          // "maintainer"` off a stranger's `owner` string — what merely got typed at it.
          did: { type: 'string', description: 'The did:web this directory recorded for the pod when its agent last authenticated here — not re-fetched or verified per call' },
          handle: { type: 'string', description: 'acct: handle resolvable via WebFinger' },
          agent: { type: 'string', description: 'Mesh agent name read off that did:web, e.g. "interego-discord-u-eth-053ad15f9633". Set only from evidence this relay recorded — never from `owner`' },
          surface: { type: 'string', description: 'Role-bearing head of that name, e.g. "interego-discord" — NOT a claim of authority' },
          identifiedBy: { type: 'string', description: '"did:web agent name" | "registered surface" | "unverified owner claim" | "nothing". The first two are evidence THIS relay recorded from an authenticated session; "unverified owner claim" means the only agent name here was typed into the caller-writable `owner` field; "nothing" means this directory holds no name at all for the pod — which does not stop the pod publishing a card elsewhere' },
          claimedAgent: { type: 'string', description: 'An agent name the row\'s `owner` field SPELLS and nothing here backs. Deliberately not `agent` — treat it as a lead to verify (fetch the DID, or ask the agent), never as the recipient' },
          claimedSurface: { type: 'string', description: 'Role-bearing head of `claimedAgent`. Same standing: somebody typed it' },
          claimNote: { type: 'string', description: 'Who can write `owner`, present whenever `claimedAgent` is' },
          identityNote: { type: 'string', description: 'Why the row is unidentified here, when it is' },
          affordances: {
            type: 'array',
            description:
              'What you can DO with this row, as a link you follow rather than fields you retype. '
              + 'Each entry is an iep:Affordance / hydra:Operation carrying `arguments` (the '
              + 'request body to POST at `target`, already addressed to THIS row\u2019s agent) and '
              + '`iep:agentIdentity` (the same address as an IRI, dereferenceable so you can see '
              + 'whose it is before you send). PRESENT ONLY on a row this relay identified AND '
              + 'can mint a resolvable address for: absence means there is nothing here to '
              + 'follow, not that the pod cannot be messaged.',
            items: {
              type: 'object',
              properties: {
                action: { type: 'string', description: 'The action id, under this relay\u2019s naming authority — it dereferences' },
                target: { type: 'string', description: 'The invokable endpoint for the operation (POST /tool/notify_agent)' },
                method: { type: 'string' },
                arguments: { type: 'object', description: 'The request body, pre-filled with `to`. Add `summary` and POST it to `target`' },
                'iep:agentIdentity': { type: 'object', description: 'The bound recipient address as a JSON-LD node object ({"@id": …}) — derived from what this relay observed, never from `owner` or `label`' },
                expects: { type: 'string', description: 'URL of the operation\u2019s request JSON Schema' },
                returns: { type: 'string', description: 'URL of the operation\u2019s response JSON Schema' },
              },
            },
          },
        },
        required: ['url'],
      },
    },
  },
});

